import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import MainMenu from './components/MainMenu';
// Werewolf game components
import WerewolfSetup from './games/werewolf/components/WerewolfSetup';
import WerewolfJoin from './games/werewolf/components/WerewolfJoin';

function App() {
  return (
    <div className="app">
      <Router>
        <Routes>
          {/* Main hub */}
          <Route path="/" element={<MainMenu />} />
          
          {/* Werewolf game routes */}
          <Route path="/games/werewolf/setup" element={<WerewolfSetup />} />
          <Route path="/games/werewolf/join" element={<WerewolfJoin />} />
          
          {/* Legacy routes for backward compatibility */}
          <Route path="/TiAlbertSetup" element={<WerewolfSetup />} />
          <Route path="/join" element={<WerewolfJoin />} />
          
          {/* Future game routes will go here */}
          {/* <Route path="/games/mafia/setup" element={<MafiaSetup />} /> */}
          {/* <Route path="/games/mafia/join" element={<MafiaJoin />} /> */}
        </Routes>
      </Router>
    </div>
  );
}

export default App;
